<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\SpecialCategoryService;
Auth::requireAdmin();$pdo=Database::connection();$roundId=(int)($_POST['round_id']??0);$mode=(string)($_SESSION['bdc_test_scoring_mode']??'manual');if(!in_array($mode,['manual','automated'],true))$mode='manual';
try{if($_SERVER['REQUEST_METHOD']!=='POST'||!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$s=$pdo->prepare('SELECT division FROM bdc_test_scoring_rounds WHERE id=:id');$s->execute(['id'=>$roundId]);$division=(string)$s->fetchColumn();if(!SpecialCategoryService::isSpecial($division))throw new RuntimeException('Special-category test round not found.');$m=$pdo->prepare("SELECT COUNT(*) FROM bdc_test_scoring_marks WHERE round_id=:id AND (mark_type<>'blank' OR weighted_score>0)");$m->execute(['id'=>$roundId]);if((int)$m->fetchColumn()>0)throw new RuntimeException('The YES count cannot be changed or unlocked after judging has started.');$action=(string)($_POST['action']??'');if($action==='special_settings_lock'){$yes=max(1,min(100,(int)($_POST['special_yes_count']??10)));$pdo->prepare('UPDATE bdc_test_scoring_rounds SET yes_count=:yes,callback_count=:yes,tier_manual_override=1,yes_weight=10.00,alt1_weight=4.50,alt2_weight=4.30,alt3_weight=4.20 WHERE id=:id')->execute(['yes'=>$yes,'id'=>$roundId]);}elseif($action==='special_settings_unlock'){$pdo->prepare('UPDATE bdc_test_scoring_rounds SET tier_manual_override=0 WHERE id=:id')->execute(['id'=>$roundId]);}else throw new RuntimeException('Invalid special-category settings action.');}catch(Throwable $e){$_SESSION['bdc_test_auto_error']=$e->getMessage();}
header('Location: dashboard.php?test_mode='.$mode.'&round_id='.$roundId,true,303);exit;
